  "/targets.html": { type: "text/html; charset=utf-8", body: "<!doctype html>\n<html lang=\"en\"><head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width\">\n<title>Target-size + focus-obscured fixture</title>\n<style>\n  body { font-family: system-ui; margin: 0; padding-top: 0; }\n  /* sticky banner sits over the nav link — Tab focuses it, but it's hidden */\n  .banner { position: fixed; top: 0; left: 0; right: 0; height: 90px;\n            background: #fff; border-bottom: 1px solid #ddd; z-index: 99;\n            padding: 20px; }\n  nav { margin-top: 0; padding: 30px 20px; }\n  main { padding: 40px 20px; }\n  .icon { width: 16px; height: 16px; padding: 0; font-size: 9px;\n          line-height: 1; }\n</style>\n</head><body>\n<div class=\"banner\">We use cookies. This banner never goes away.</div>\n<nav>\n  <a href=\"/home\" id=\"covered\">Home (under the banner)</a>\n</nav>\n<main>\n  <p><a href=\"/about\">About link inside a paragraph — inline exception</a></p>\n  <button class=\"icon\">★</button>\n  <button class=\"icon\">✓</button>\n  <a href=\"/docs\">Docs</a>\n</main>\n</body></html>\n" },
  "/targets2.html": { type: "text/html; charset=utf-8", body: "<!doctype html>\n<html lang=\"en\">\n<head>\n<title>Non-text contrast + spacing + focus-indicator fixture</title>\n<style>\n  body{font:16px/1.4 sans-serif;background:#fff}\n  /* 1.4.11: field border ~1.2:1 against white — invisible boundary */\n  .faint{border:1px solid #eee;background:#fff;padding:8px}\n  /* 1.4.12: text fits at normal spacing but clips under WCAG overrides */\n  .clip{height:46px;overflow:hidden;width:280px}\n  /* 2.4.13: focused element loses its only indicator, no replacement */\n  .noind:focus{outline:none}\n  /* 1.4.1: prose link with no underline and same color as body text */\n  .barelink{text-decoration:none;color:#141414}\n</style>\n</head>\n<body>\n<main>\n<a href=\"/\">nav</a>\n<label>Email <input class=\"faint\" type=\"email\" name=\"e\"></label>\n<div class=\"clip\"><p style=\"margin:0\">Fixture text sized to exactly two lines</p></div>\n<a href=\"/ok\" class=\"noind\">focus me</a>\n<p>Body text with a <a class=\"barelink\" href=\"/x\">color-only link</a> inside it.</p>\n</main>\n</body>\n</html>\n" },
  "/trap.html": { type: "text/html; charset=utf-8", body: "<!DOCTYPE html>\n<html lang=\"en\">\n<head><meta charset=\"utf-8\"><title>Keyboard trap fixture</title></head>\n<body>\n  <main>\n    <h1>Trap fixture</h1>\n    <a href=\"#top\">top link</a>\n    <div id=\"trap-region\">\n      <button id=\"t1\">trap one</button>\n      <button id=\"t2\">trap two</button>\n    </div>\n    <a href=\"#never\">never reached</a>\n  </main>\n  <script>\n    // A real keyboard trap: once focus enters #trap-region, Tab/Shift+Tab are\n    // hijacked to cycle between the two buttons forever — focus can never\n    // reach the \"never reached\" link or leave the region by keyboard.\n    const a = document.getElementById('t1'), b = document.getElementById('t2');\n    for (const el of [a, b]) {\n      el.addEventListener('keydown', (e) => {\n        if (e.key === 'Tab') {\n          e.preventDefault();\n          (e.target === a ? b : a).focus();\n        }\n      });\n    }\n  </script>\n</body>\n</html>\n" },
